/// <summary>
/// Set pricing rule Rec Id to trade agreement line
/// </summary>
/// <param name = "_pricingRuleFieldId">Pricing rule fields depends on source level</param>
/// <param name = "_pricingRuleRecID">Pricing rule reference</param>
public void setPricingRuleReference(FieldId _pricingRuleFieldId, RefRecId _pricingRuleRecID)
{
    ttsbegin;

    this.selectForUpdate(true);
    this.(_pricingRuleFieldId) = _pricingRuleRecID; 

    this.update();

    ttscommit;
}

/// <summary>
/// Display pricing attribute group name for header group
/// </summary>
/// <returns>Pricing attribute group name</returns>
[SysClientCacheDataMethodAttribute(true)]
public display UPSPricingAttributeGroupNameHeader displayPricingAttributeGroupNameHeader()
{
    return UPSPricingRule::find(this.PricingRuleHeader).pricingAttributeGroup().Name;
}

/// <summary>
/// Display pricing attribute group name for line group
/// </summary>
/// <returns>Pricing attribute group name</returns>
[SysClientCacheDataMethodAttribute(true)]
public display UPSPricingAttributeGroupNameLine displayPricingAttributeGroupNameLine()
{
    return UPSPricingRule::find(this.PricingRuleLine).pricingAttributeGroup().Name;
}

/// <summary>
/// Display pricing attributes related to Header pricing group
/// </summary>
/// <returns>Pricing attribute details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display UPSPricingAttributeDetails pricingAttributeDetailsHeader()
{
    return this.getPricingAttributeDetails(this.PricingRuleHeader);
}

/// <summary>
/// Display pricing attributes related to Line pricing group
/// </summary>
/// <returns>Pricing attribute details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display UPSPricingAttributeDetails pricingAttributeDetailsLine()
{
    return this.getPricingAttributeDetails(this.PricingRuleLine);
}

/// <summary>
/// Find and format pricing attributes with related conditions
/// </summary>
/// <param name = "_pricingRuleRecId">Pricing rule reference</param>
/// <returns>Pricing attributes with related conditions</returns>
public UPSPricingAttributeDetails getPricingAttributeDetails(UPSPricingRuleRecId _pricingRuleRecId)
{
    UPSPricingRuleCondition     pricingRuleCondition;
    UPSPricingAttributeDetails  displayDetails;

    UPSPricingAttributeRepository::getAllPricingAttributes();

    while select pricingRuleCondition
        where pricingRuleCondition.RuleId == _pricingRuleRecId
    {
        str conditionValue = UPSPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                                                                            pricingRuleCondition.pricingAttribute().getName(),
                                                                            pricingRuleCondition.ConditionValue);

        displayDetails += strFmt('%1: %2; ',
                                    pricingRuleCondition.pricingAttribute().getName(),
                                    conditionValue);
    }

    return displayDetails;
}

/// <summary>
/// Validates the item relation value. 
/// For pricing attributes this validation should skip item validation and run pricing group validation instead
/// </summary>
/// <returns>true if the item relation value is valid; otherwise, false.</returns>
protected boolean isItemRelationValid()
{
    boolean ok = next isItemRelationValid();

    if (!this.isPricingAttributeEnabled())
        return ok;

    ok = true;

    ok = ok && this.checkPricingAttributeValid(this.PricingGroupCodeHeader, this.PricingRuleHeader);
    ok = ok && this.checkPricingAttributeValid(this.PricingGroupCodeLine, this.PricingRuleLine);

    return ok;
}

/// <summary>
/// Validate pricing group specified for group code type
/// </summary>
/// <param name = "_codeType">Group code type</param>
/// <param name = "_pricingRuleRecId">Pricing group of trade agreement line (header/line)</param>
/// <returns>True if pricing group is correct; Otherwise false</returns>
public boolean checkPricingAttributeValid(UPSGroupAll _codeType, UPSPricingRuleRecId _pricingRuleRecId)
{
    boolean ok = true;

    switch (_codeType)
    {
        case UPSGroupAll::Group:
            if (!UPSPricingRule::find(_pricingRuleRecId).PriceAttributeGroup)
            {
                ok = false;
            }
            break;
        case UPSGroupAll::All:
            if (UPSPricingRule::find(_pricingRuleRecId).PriceAttributeGroup)
            {
                ok = false;
            }
    }

    return ok;
}

/// <summary>
///     Initializing the Price and Discount record.
/// </summary>
public void initValue()
{
    next initValue();

    if (this.isPricingAttributeEnabled())
    {
        this.PricingGroupCodeHeader = UPSGroupAll::All;
        this.PricingGroupCodeLine   = UPSGroupAll::All;
    }
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_priceDiscAdmTrans">
/// A <c>PriceDiscAdmTrans</c> table buffer.
/// </param>
public void initFromPriceDiscAdmTrans(PriceDiscAdmTrans _priceDiscAdmTrans)
{
    next initFromPriceDiscAdmTrans(_priceDiscAdmTrans);

    this.PricingGroupCodeHeader = _priceDiscAdmTrans.PricingGroupCodeHeader;
    this.PricingGroupCodeLine   = _priceDiscAdmTrans.PricingGroupCodeLine;
    this.PricingRuleHeader      = _priceDiscAdmTrans.PricingRuleHeader;
    this.PricingRuleLine        = _priceDiscAdmTrans.PricingRuleLine;
}

/// <summary>
///     Initiates a <c>PriceDiscAdmTrans</c> record from a <c>PriceDiscTable</c> record.
/// </summary>
/// <param name="_priceDiscTable">
///     A <c>PriceDiscTable</c> record buffer.
/// </param>
public void initFromPriceDiscTable(PriceDiscTable _priceDiscTable)
{
    next initFromPriceDiscTable(_priceDiscTable);

    this.PricingGroupCodeHeader = _priceDiscTable.PricingGroupCodeHeader;
    this.PricingGroupCodeLine   = _priceDiscTable.PricingGroupCodeLine;
    this.PricingRuleHeader      = _priceDiscTable.PricingRuleHeader;
    this.PricingRuleLine        = _priceDiscTable.PricingRuleLine;
}

/// <summary>
/// Specifies if current journal is enabled for pricing attributes
/// </summary>
/// <returns>True if pricing attributes are enabled in journal name record; Otherwise false</returns>
public boolean isPricingAttributeEnabled()
{
    PriceDiscAdmTable   priceDiscAdmTable = PriceDiscAdmTable::find(this.JournalNum);
    PriceDiscAdmName    priceDiscAdmName = PriceDiscAdmName::find(priceDiscAdmTable.JournalName);

    return priceDiscAdmName.PriceDiscPriceAttributeEnable;
}
